package kube

import (
	"encoding/json"

	"clawreef/internal/systembackup/worker"
	corev1 "k8s.io/api/core/v1"
)

// WorkerConfigMap is immutable and contains no DSN, plaintext key or credentials.
// Its lifecycle is journaled like the Job; the TLS identity is issued separately
// by the shared identity provider and is never generated by this builder.
func WorkerConfigMap(i Identity, invocation worker.Invocation) (*corev1.ConfigMap, error) {
	r := invocation.Request
	if !i.valid() || r.Version != worker.Version || r.Deadline.IsZero() || invocation.StagingPath != "/staging" {
		return nil, ErrResource
	}
	switch r.Operation {
	case "capture-workspace", "restore-workspace", "restore-assets", "verify-assets":
		if invocation.WorkspacePath != "/workspace" || invocation.EvidencePath != "" || r.Database != nil {
			return nil, ErrResource
		}
	case "capture-database", "verify-database", "restore-database":
		if invocation.WorkspacePath != "" || r.Database == nil {
			return nil, ErrResource
		}
		if r.Operation == "restore-database" {
			if invocation.EvidencePath != "/evidence" {
				return nil, ErrResource
			}
		} else if invocation.EvidencePath != "" {
			return nil, ErrResource
		}
	default:
		return nil, ErrResource
	}
	b, e := json.Marshal(invocation)
	if e != nil || len(b) > 512<<10 {
		return nil, ErrResource
	}
	immutable := true
	return &corev1.ConfigMap{ObjectMeta: i.meta(), Immutable: &immutable, Data: map[string]string{"invocation.json": string(b)}}, nil
}
